export function createClient(options = {}) {
  return { timeoutMs: options.timeoutMs ?? options.timeout ?? 1000 };
}

export function createServer(options = {}) {
  return {
    timeoutMs: options.timeoutMs ?? options.timeout ?? 5000,
    port: options.port ?? 80,
  };
}

export const DEFAULTS = { timeoutMs: 1000 };

export function describe(options = {}) {
  return (
    'timeoutMs=' +
    (options.timeoutMs ?? options.timeout ?? DEFAULTS.timeoutMs)
  );
}
